DECLARE @Reader TABLE (ReaderId int, NickName nvarchar(20));
INSERT INTO @Reader VALUES (1, NULL);
SELECT ISNULL(NickName, N'(未設定)') FROM @Reader   -- '(未設定)'

DECLARE @s varchar(2) = NULL, @Code varchar(10) = 'A01';
SELECT ISNULL(@s, 'abc') AS [ISNULL], COALESCE(@s, 'abc') AS [COALESCE];   -- 'ab' | 'abc'
SELECT ISNULL(@Code, 0) AS [ISNULL];   -- 'A01'；換成 COALESCE(@Code, 0) 會報錯

DECLARE @Code varchar(10) = 'A01';
SELECT ISNULL(@Code, 0) AS [ISNULL];       -- 'A01'
SELECT COALESCE(@Code, 0) AS [COALESCE];   -- 錯誤：@Code 不是 NULL，但型別取 int，'A01' 轉不成 int

DECLARE @Code varchar(10) = 'A01', @Qty int = NULL;
SELECT COALESCE(@Code, '0') AS Code,                       -- 'A01'
       COALESCE(CAST(@Qty AS varchar(10)), 'N/A') AS Qty   -- 'N/A'

DECLARE @Copy TABLE (CopyNo int, LoanCount int);
INSERT INTO @Copy VALUES (1, 0);
SELECT CopyNo, 100.0 / NULLIF(LoanCount, 0) AS AvgLoad FROM @Copy   -- NULL，不拋出除以零

DECLARE @Copy TABLE (CopyNo int, Status tinyint);
INSERT INTO @Copy VALUES (1, 1), (2, 0);
SELECT CopyNo, IIF(Status = 1, N'借出', N'在架') FROM @Copy ORDER BY CopyNo   -- 1: 借出；2: 在架

DECLARE @Copy TABLE (CopyNo varchar(10));
INSERT INTO @Copy VALUES ('A01'), (NULL), ('A02');
SELECT STRING_AGG(CopyNo, ', ') WITHIN GROUP (ORDER BY CopyNo) FROM @Copy   -- 'A01, A02'（NULL 直接略過，不留分隔字元）

DECLARE @Copy TABLE (BranchId int, CopyNo varchar(10));
INSERT INTO @Copy VALUES (1, 'A01'), (1, 'A02'), (2, 'B01');
SELECT BranchId, STRING_AGG(CopyNo, ', ') WITHIN GROUP (ORDER BY CopyNo)
FROM @Copy GROUP BY BranchId ORDER BY BranchId   -- 1: 'A01, A02'；2: 'B01'

DECLARE @t TABLE (Id int, D date);
INSERT INTO @t VALUES (1,'2026-01-01'),(2,'2026-01-01'),(3,'2026-01-02'),(4,'2026-01-03');
SELECT Id,
       ROW_NUMBER() OVER (ORDER BY D) AS RowNum,
       RANK()       OVER (ORDER BY D) AS Rnk,
       DENSE_RANK() OVER (ORDER BY D) AS DenseRnk
FROM @t ORDER BY D;
-- 前兩筆同分：RowNum 給 1、2，Rnk 都是 1，DenseRnk 都是 1；
-- 第三筆 Rnk 跳到 3、DenseRnk 只到 2；第四筆 Rnk=4、DenseRnk=3

DECLARE @t TABLE (Id int, D date);
INSERT INTO @t VALUES (1,'2026-01-01'),(2,'2026-01-01'),(3,'2026-01-02'),(4,'2026-01-03');
SELECT Id,
       ROW_NUMBER() OVER (ORDER BY D) AS RowNum,
       RANK()       OVER (ORDER BY D) AS Rnk,
       DENSE_RANK() OVER (ORDER BY D) AS DenseRnk
FROM @t ORDER BY D;
-- 前兩筆同分：DenseRnk 都是 1；第三筆是 2（不跳號）；同一筆的 Rnk 卻是 3

DECLARE @t TABLE (Id int, D date);
INSERT INTO @t VALUES (1,'2026-01-01'),(2,'2026-01-01'),(3,'2026-01-02'),(4,'2026-01-03');
SELECT Id,
       ROW_NUMBER() OVER (ORDER BY D) AS RowNum,
       RANK()       OVER (ORDER BY D) AS Rnk,
       DENSE_RANK() OVER (ORDER BY D) AS DenseRnk
FROM @t ORDER BY D;
-- 前兩筆同分：Rnk 都是 1；第三筆跳號變成 3（略過名次 2）；第四筆是 4

DECLARE @Copy TABLE (CopyNo varchar(10));
INSERT INTO @Copy VALUES ('A01'), ('A02'), ('A03');
SELECT STUFF((
  SELECT ', ' + CopyNo FROM @Copy ORDER BY CopyNo FOR XML PATH('')
), 1, 2, '')   -- 'A01, A02, A03'；SQL Server 2017 起改用 STRING_AGG 更直覺

CREATE TABLE #t (Id int);
SELECT OBJECT_ID('#t') AS NotFound, OBJECT_ID('tempdb..#t') AS Found;
DROP TABLE #t;
-- NotFound 是 NULL（在目前資料庫找）；Found 有值（要加 tempdb.. 前綴）

CREATE TABLE dbo.Lib_Tag (Id int IDENTITY, Name nvarchar(50));
CREATE TABLE dbo.Lib_TagLog (Id int IDENTITY(100,1), TagId int);
GO
CREATE TRIGGER trg_Lib_Tag_Log ON dbo.Lib_Tag AFTER INSERT AS
  INSERT INTO dbo.Lib_TagLog (TagId) SELECT Id FROM inserted;
GO
INSERT INTO dbo.Lib_Tag (Name) VALUES ('Fiction');
SELECT SCOPE_IDENTITY() AS ScopeId, @@IDENTITY AS GlobalId, IDENT_CURRENT('dbo.Lib_Tag') AS CurrentId;
-- ScopeId=1（Lib_Tag 這列的值）；GlobalId=100（被 Lib_TagLog 的識別值蓋過）；CurrentId=1（只看 Lib_Tag）
DROP TABLE dbo.Lib_Tag; DROP TABLE dbo.Lib_TagLog;

